#ifndef SCAMP_FIB_HPP
#define SCAMP_FIB_HPP
// Normalized 128-bit forwarding information base helpers shared by the live
// trie, the compact image exporter and the image loader/validator.
#include <algorithm>
#include <bitset>
#include <cstdint>
#include <unordered_map>
#include <vector>

static const uint32_t FIB_NO_HOP = 0xFFFFFFFFu;
static const uint32_t BMP_NULL_VALUE = 4194303u;   // 22-bit null forwarding value
static const uint32_t HOP_MAX_VALUE = 4194302u;
static const uint32_t FIB_MAX_PREFIXES = 8192u;

struct FibPfx {
    uint64_t hi;
    uint64_t lo;
    uint32_t len;
    uint32_t hop;
};

inline uint64_t fib_mask_high(uint64_t v, uint32_t bits) {
    if (bits == 0u) return 0u;
    if (bits >= 64u) return v;
    return (v >> (64u - bits)) << (64u - bits);
}

// Clear host bits of a 128-bit prefix.
inline void fib_normalize(uint64_t hi, uint64_t lo, uint32_t len, uint64_t& oh, uint64_t& ol) {
    if (len >= 64u) { oh = hi; ol = fib_mask_high(lo, len - 64u); }
    else { oh = fib_mask_high(hi, len); ol = 0u; }
}

// bits [start, start+count) of the 128-bit value, MSB first, count <= 64
inline uint64_t fib_bits(uint64_t hi, uint64_t lo, uint32_t start, uint32_t count) {
    uint64_t v = 0;
    for (uint32_t i = 0; i < count; ++i) {
        uint32_t b = start + i;
        uint64_t bit = (b < 64u) ? ((hi >> (63u - b)) & 1ULL) : ((lo >> (127u - b)) & 1ULL);
        v = (v << 1) | bit;
    }
    return v;
}

// set 'count' bits (value v, right aligned) at [start, start+count)
inline void fib_set_bits(uint64_t& hi, uint64_t& lo, uint32_t start, uint32_t count, uint64_t v) {
    for (uint32_t i = 0; i < count; ++i) {
        uint32_t b = start + i;
        uint64_t bit = (v >> (count - 1u - i)) & 1ULL;
        if (bit) {
            if (b < 64u) hi |= (1ULL << (63u - b));
            else lo |= (1ULL << (127u - b));
        }
    }
}

class Fib {
public:
    struct Key {
        uint64_t hi, lo;
        bool operator==(const Key& o) const { return hi == o.hi && lo == o.lo; }
    };
    struct KeyHash {
        size_t operator()(const Key& k) const {
            uint64_t x = k.hi * 0x9E3779B97F4A7C15ULL + k.lo * 0xC2B2AE3D27D4EB4FULL;
            x ^= x >> 31; x *= 0x94D049BB133111EBULL; x ^= x >> 29;
            return static_cast<size_t>(x);
        }
    };

    Fib() {}

    size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }

    // insert/replace a normalized prefix: last write wins
    void insert(uint64_t hi, uint64_t lo, uint32_t len, uint32_t hop) {
        if (len > 128u) return;
        uint64_t nh, nl;
        fib_normalize(hi, lo, len, nh, nl);
        Key k{nh, nl};
        std::unordered_map<Key, uint32_t, KeyHash>& m = by_len_[len];
        auto it = m.find(k);
        if (it != m.end()) { it->second = hop; return; }
        m.emplace(k, hop);
        ++count_;
        if (!used_.test(len)) {
            used_.set(len);
            lens_.push_back(static_cast<uint8_t>(len));
            std::sort(lens_.begin(), lens_.end(), std::greater<uint8_t>());
        }
    }

    static Key make_key(uint64_t hi, uint64_t lo, uint32_t len) {
        uint64_t nh, nl;
        fib_normalize(hi, lo, len, nh, nl);
        return Key{nh, nl};
    }

    // longest matching prefix with length <= max_len, FIB_NO_HOP when none
    uint32_t lookup_upto(uint64_t hi, uint64_t lo, uint32_t max_len) const {
        for (size_t i = 0; i < lens_.size(); ++i) {
            uint32_t len = lens_[i];
            if (len > max_len) continue;
            auto it = by_len_[len].find(make_key(hi, lo, len));
            if (it != by_len_[len].end()) return it->second;
        }
        return FIB_NO_HOP;
    }

    uint32_t lookup(uint64_t hi, uint64_t lo) const { return lookup_upto(hi, lo, 128u); }

    bool contains(uint64_t hi, uint64_t lo, uint32_t len) const {
        if (len > 128u) return false;
        return by_len_[len].find(make_key(hi, lo, len)) != by_len_[len].end();
    }

    std::vector<FibPfx> all() const {
        std::vector<FibPfx> out;
        out.reserve(count_);
        for (uint32_t len = 0; len <= 128u; ++len) {
            for (auto& kv : by_len_[len])
                out.push_back(FibPfx{kv.first.hi, kv.first.lo, len, kv.second});
        }
        std::sort(out.begin(), out.end(), [](const FibPfx& a, const FibPfx& b) {
            if (a.len != b.len) return a.len < b.len;
            if (a.hi != b.hi) return a.hi < b.hi;
            return a.lo < b.lo;
        });
        return out;
    }

private:
    std::unordered_map<Key, uint32_t, KeyHash> by_len_[129];
    std::vector<uint8_t> lens_;
    std::bitset<129> used_;
    size_t count_ = 0;
};
#endif
